// What the dispatch and pause scripts share: arguments, the config, `gh api`, and the
// check that every configured repo is checked out and can be pushed to.
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const FOOTER =
  "\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_";
export const PAUSE_LABEL = "workshop-paused";

export const arg = (name, dflt) => {
  const i = process.argv.indexOf(name);
  return i > 0 ? process.argv[i + 1] : dflt;
};
export const flag = (name) => process.argv.includes(name);

const run = (cmd, args, input) =>
  execFileSync(cmd, args, {
    encoding: "utf8",
    input,
    maxBuffer: 1 << 26,
    // Keep stderr out of the log: a failure still throws with it attached,
    // and an expected 422 stays quiet.
    stdio: ["pipe", "pipe", "pipe"],
  });
export const api = (path, ...rest) =>
  JSON.parse(run("gh", ["api", path, ...rest]) || "null");
// --paginate --slurp yields one array per page.
export const all = (path) => api(path, "--paginate", "--slurp").flat();
export const post = (path, body, method = "POST") =>
  run("gh", ["api", "-X", method, path, "--input", "-"], JSON.stringify(body));
export const names = (x) => x.labels.map((l) => (typeof l === "string" ? l : l.name));

/**
 * The workshop config: `{digest, repos: [{repo, name, path}]}`. `--config` picks
 * the file (default: workshop.json next to this skill), `--repos a/b,c/d` limits the
 * run to some of its repos. A repo's clone is its entry's `path`, else
 * `<checkouts>/<name>`, where checkouts is `--checkouts`, $WORKSHOP_CHECKOUTS, or
 * the folder holding the clone the run started in.
 */
export const loadConfig = () => {
  const here = dirname(fileURLToPath(import.meta.url));
  const file = arg("--config", join(here, "..", "workshop.json"));
  const cfg = JSON.parse(readFileSync(file, "utf8"));
  const only = arg("--repos")?.split(",").map((r) => r.trim().toLowerCase());
  const checkouts = () =>
    arg("--checkouts") ??
    process.env.WORKSHOP_CHECKOUTS ??
    dirname(run("git", ["rev-parse", "--show-toplevel"]).trim());
  const repos = cfg.repos
    .filter((r) => !only || only.includes(r.repo.toLowerCase()))
    .map((r) => {
      const name = r.repo.split("/")[1];
      return { ...r, name, path: resolve(r.path ?? join(checkouts(), name)) };
    });
  if (only) {
    const unknown = only.filter(
      (o) => !repos.some((r) => r.repo.toLowerCase() === o),
    );
    if (unknown.length)
      throw new Error(`--repos names repos not in ${file}: ${unknown.join(", ")}`);
  }
  if (!cfg.digest || !repos.length)
    throw new Error(`${file} needs a "digest" repo and at least one entry in "repos"`);
  return { digest: cfg.digest, repos };
};

const originMatches = (url, repo) =>
  new RegExp(`github\\.com[/:]${repo.replace(/[.]/g, "\\.")}(\\.git)?/?$`, "i").test(
    url.trim(),
  );

/**
 * Stops the run, naming every configured repo that isn't checked out in this
 * session or can't be pushed to. A dry-run push writes nothing.
 */
export const preflight = (repos) => {
  const problems = [];
  for (const r of repos) {
    if (!existsSync(r.path)) {
      problems.push(`${r.repo}: not checked out at ${r.path}`);
      continue;
    }
    let url;
    try {
      url = run("git", ["-C", r.path, "remote", "get-url", "origin"]);
    } catch (e) {
      problems.push(`${r.repo}: ${r.path} is not a git clone with an origin`);
      continue;
    }
    if (!originMatches(url, r.repo)) {
      problems.push(`${r.repo}: ${r.path} is a clone of ${url.trim()}`);
      continue;
    }
    try {
      run("git", [
        "-C",
        r.path,
        "push",
        "--dry-run",
        "--quiet",
        "origin",
        "HEAD:refs/heads/claude/workshop-push-check",
      ]);
    } catch (e) {
      problems.push(
        `${r.repo}: can't push (${(e.stderr || e.message).toString().trim().split("\n").at(-1)})`,
      );
    }
  }
  if (problems.length)
    throw new Error(
      `The workshop can't run on every configured repo:\n- ${problems.join("\n- ")}\nAttach the repo to the session with push access, or remove it from the config.`,
    );
};

// Runs main(), turning a thrown error into one clear line and exit code 1.
export const main = (fn) => {
  try {
    fn();
  } catch (e) {
    console.error(`workshop: ${e.message}`);
    process.exit(1);
  }
};
